static inline bool lunar_is_auspicious_day(int year, int day_of_year)
{
    if (year < LUNAR_AUSPICIOUS_FIRST_YEAR || year > LUNAR_AUSPICIOUS_LAST_YEAR ||
        day_of_year < 1 || day_of_year > 366) {
        return false;
    }
    size_t index = 0;
    for (int current_year = LUNAR_AUSPICIOUS_FIRST_YEAR; current_year < year; current_year++) {
        index += (current_year % 4 == 0 && (current_year % 100 != 0 || current_year % 400 == 0)) ? 366 : 365;
    }
    index += (size_t)(day_of_year - 1);
    return (lunar_auspicious_day_bits[index / 8] & (1U << (index % 8))) != 0;
}

static inline unsigned char lunar_day_deity_index(int year, int day_of_year)
{
    size_t index = 0;
    for (int current_year = LUNAR_AUSPICIOUS_FIRST_YEAR; current_year < year; current_year++) {
        index += (current_year % 4 == 0 && (current_year % 100 != 0 || current_year % 400 == 0)) ? 366 : 365;
    }
    index += (size_t)(day_of_year - 1);
    return (lunar_day_deity_indices[index / 2] >> (4 * (index % 2))) & 0x0F;
}

/* 0 = 建, 1 = 除, ... 11 = 闭; the 十二建除 of the day. */
static inline unsigned char lunar_day_officer_index(int year, int day_of_year)
{
    size_t index = 0;
    for (int current_year = LUNAR_AUSPICIOUS_FIRST_YEAR; current_year < year; current_year++) {
        index += (current_year % 4 == 0 && (current_year % 100 != 0 || current_year % 400 == 0)) ? 366 : 365;
    }
    index += (size_t)(day_of_year - 1);
    return (lunar_day_officer_indices[index / 2] >> (4 * (index % 2))) & 0x0F;
}

